mapper.select:
select p.id, p.batch_id, p.rabbit_id, p.check_date, p.result, p.remark, p.create_by, p.create_time, p.update_by, p.update_time
from pregnancy_check_records p
inner join batches b on b.id = p.batch_id
where b.house_id = #{houseId} and p.batch_id = #{batchId}
order by p.id desc
limit #{limit}

select p.id, p.batch_id, p.rabbit_id, p.check_date, p.result, p.remark, p.create_by, p.create_time, p.update_by, p.update_time
from pregnancy_check_records p
inner join rabbits r on r.id = p.rabbit_id
where r.house_id = #{houseId} and p.rabbit_id = #{rabbitId}
order by p.id desc
limit #{limit}
